// Generate Zotero RDF format
const book = $('Get Book').first().json;
const annotations = $('Get Annotations').all().map(i => i.json);
const highlights = $('Get Highlights').all().map(i => i.json);
const userNotes = $('Get User Notes').all().map(i => i.json);
const exportFormat = $('Webhook').item.json.format || 'rdf'; // rdf, json, markdown

// Helper to escape XML
const escapeXml = (str) => {
  if (!str) return '';
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
};

if (exportFormat === 'rdf') {
  // Generate Zotero-compatible RDF/XML
  const rdf = `<?xml version="1.0" encoding="UTF-8"?>
<rdf:RDF
  xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#"
  xmlns:z="http://www.zotero.org/namespaces/export#"
  xmlns:dc="http://purl.org/dc/elements/1.1/"
  xmlns:dcterms="http://purl.org/dc/terms/"
  xmlns:bib="http://purl.org/net/biblio#"
  xmlns:foaf="http://xmlns.com/foaf/0.1/">

  <bib:Book rdf:about="urn:isbn:${escapeXml(book.isbn || book.id)}">
    <dc:title>${escapeXml(book.title)}</dc:title>
    <dc:creator>
      <foaf:Person>
        <foaf:surname>${escapeXml(book.author?.split(' ').pop() || '')}</foaf:surname>
        <foaf:givenName>${escapeXml(book.author?.split(' ').slice(0, -1).join(' ') || '')}</foaf:givenName>
      </foaf:Person>
    </dc:creator>
    ${book.publisher ? `<dc:publisher>${escapeXml(book.publisher)}</dc:publisher>` : ''}
    ${book.year ? `<dc:date>${escapeXml(book.year)}</dc:date>` : ''}
    ${book.isbn ? `<dc:identifier>ISBN ${escapeXml(book.isbn)}</dc:identifier>` : ''}
  </bib:Book>

${annotations.map((ann, i) => `
  <bib:Memo rdf:about="#annotation-${i}">
    <rdf:value>${escapeXml(ann.term)}: ${escapeXml(ann.explanation)}</rdf:value>
    <dc:subject>${escapeXml(ann.annotation_type)}</dc:subject>
    <dcterms:isPartOf rdf:resource="urn:isbn:${escapeXml(book.isbn || book.id)}"/>
    ${ann.wikipedia_url ? `<dc:relation>${escapeXml(ann.wikipedia_url)}</dc:relation>` : ''}
  </bib:Memo>`).join('')}

${highlights.map((hl, i) => `
  <bib:Memo rdf:about="#highlight-${i}">
    <rdf:value>${escapeXml(hl.text)}</rdf:value>
    <dc:subject>highlight</dc:subject>
    <z:color>${escapeXml(hl.color || 'yellow')}</z:color>
    <dcterms:isPartOf rdf:resource="urn:isbn:${escapeXml(book.isbn || book.id)}"/>
    ${hl.note ? `<z:note>${escapeXml(hl.note)}</z:note>` : ''}
  </bib:Memo>`).join('')}

${userNotes.map((note, i) => `
  <bib:Memo rdf:about="#note-${i}">
    <rdf:value>${escapeXml(note.content)}</rdf:value>
    <dc:subject>note</dc:subject>
    <dcterms:isPartOf rdf:resource="urn:isbn:${escapeXml(book.isbn || book.id)}"/>
    <dc:date>${escapeXml(note.created_at)}</dc:date>
  </bib:Memo>`).join('')}

</rdf:RDF>`;

  return {
    json: {
      format: 'rdf',
      filename: `${book.title.replace(/[^a-z0-9]/gi, '_')}_annotations.rdf`,
      content: rdf,
      mimeType: 'application/rdf+xml'
    }
  };
}

if (exportFormat === 'json') {
  // Zotero JSON format
  const zoteroJson = {
    items: [
      {
        itemType: 'book',
        title: book.title,
        creators: [{
          creatorType: 'author',
          firstName: book.author?.split(' ').slice(0, -1).join(' ') || '',
          lastName: book.author?.split(' ').pop() || ''
        }],
        publisher: book.publisher || '',
        date: book.year || '',
        ISBN: book.isbn || '',
        notes: [
          ...annotations.map(ann => ({
            itemType: 'note',
            note: `<h3>${ann.term}</h3><p>${ann.explanation}</p>${ann.wikipedia_url ? `<p><a href="${ann.wikipedia_url}">Wikipedia</a></p>` : ''}`,
            tags: [{ tag: ann.annotation_type }]
          })),
          ...highlights.map(hl => ({
            itemType: 'note',
            note: `<blockquote>${hl.text}</blockquote>${hl.note ? `<p>${hl.note}</p>` : ''}`,
            tags: [{ tag: 'highlight' }, { tag: hl.color || 'yellow' }]
          })),
          ...userNotes.map(note => ({
            itemType: 'note',
            note: note.content,
            tags: [{ tag: 'personal-note' }]
          }))
        ]
      }
    ]
  };

  return {
    json: {
      format: 'json',
      filename: `${book.title.replace(/[^a-z0-9]/gi, '_')}_annotations.json`,
      content: JSON.stringify(zoteroJson, null, 2),
      mimeType: 'application/json'
    }
  };
}

// Markdown format (for easy reading/sharing)
const markdown = `# ${book.title}
**Author:** ${book.author || 'Unknown'}
${book.year ? `**Year:** ${book.year}` : ''}
${book.isbn ? `**ISBN:** ${book.isbn}` : ''}

---

## Annotations

${annotations.map(ann => `### ${ann.term}
*Type: ${ann.annotation_type}*

${ann.explanation}

${ann.wikipedia_url ? `[Wikipedia](${ann.wikipedia_url})` : ''}
`).join('\n')}

---

## Highlights

${highlights.map(hl => `> ${hl.text}

${hl.note ? `*Note: ${hl.note}*` : ''}
`).join('\n')}

---

## Notes

${userNotes.map(note => `- ${note.content}
`).join('\n')}

---
*Exported from WikiRead Scholar on ${new Date().toISOString().split('T')[0]}*
`;

return {
  json: {
    format: 'markdown',
    filename: `${book.title.replace(/[^a-z0-9]/gi, '_')}_annotations.md`,
    content: markdown,
    mimeType: 'text/markdown'
  }
};
